node -e '
const fs = require("fs");
const lines = fs.readFileSync("/reference/glossary.md", "utf8").split("\n");
const entries = [];
for (const line of lines) {
  if (line.startsWith("| ") && !line.startsWith("| symbol ") && !line.startsWith("|---")) {
    const parts = line.split("|").map(s => s.trim());
    if (parts.length >= 4) {
      entries.push({ symbol: parts[1], kind: parts[2], signature: parts[3] });
    }
  }
}
console.log("Total entries:", entries.length);
console.log("Kinds:", [...new Set(entries.map(e => e.kind))]);
console.log("Constructors:", entries.filter(e => e.kind === "constructor").map(e => e.symbol).join(", "));
console.log("Composites:", entries.filter(e => e.kind === "composite").map(e => e.symbol).join(", "));
console.log("Claim relations:", entries.filter(e => e.kind === "claim_relation").map(e => e.symbol).join(", "));
console.log("Speech acts:", entries.filter(e => e.kind === "speech_act").map(e => e.symbol).join(", "));
console.log("Links:", entries.filter(e => e.kind === "link").map(e => e.symbol).join(", "));
console.log("Operations:", entries.filter(e => e.kind === "operation").map(e => e.symbol).join(", "));
'

