const fs = require("fs");
const lines = fs.readFileSync("/reference/glossary.md", "utf8").split("\n");
const valuesByCategory = {};
for (const line of lines) {
  if (line.startsWith("| ") && !line.startsWith("| symbol ") && !line.startsWith("|---")) {
    const parts = line.split("|").map(s => s.trim());
    if (parts[2] === "value") {
      const cat = parts[4] || "uncategorized";
      valuesByCategory[cat] = valuesByCategory[cat] || [];
      valuesByCategory[cat].push(parts[1]);
    }
  }
}
console.log(Object.keys(valuesByCategory));
for (const [k, v] of Object.entries(valuesByCategory)) {
  console.log(k, ":", v.join(", "));
}
'

